#!/usr/bin/env python3
"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def read_text(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    text = read_text(path)
    rows = []
    for row in csv.DictReader(text.splitlines(True) and __import__("io").StringIO(text, newline="")):
        rows.append({(k or "").strip(): (v if v is not None else "") for k, v in row.items()})
    return rows


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def pdate(s):
    y, m, d = s.strip().split("-")
    return date(int(y), int(m), int(d))


def pnum(s):
    d = re.sub(r"\D", "", s or "")
    return int(d) if d else None


def parse_offset(s):
    s = s.strip()
    sign = -1 if s.startswith("-") else 1
    s = s.lstrip("+-")
    h, m = s.split(":")[:2]
    return sign * (int(h) * 60 + int(m))


def parse_instant(s):
    """Return aware UTC datetime for an ISO 8601 string."""
    s = s.strip()
    m = re.match(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|z|[+-]\d\d:?\d\d)?$", s)
    if not m:
        raise ValueError(s)
    y, mo, d, h, mi, se, tz = m.groups()
    dt = datetime(int(y), int(mo), int(d), int(h), int(mi), int(se or 0))
    if tz is None or tz in "Zz":
        off = 0
    else:
        t = tz.replace(":", "")
        off = (1 if t[0] == "+" else -1) * (int(t[1:3]) * 60 + int(t[3:5]))
    return dt - timedelta(minutes=off)


def load_policy(path):
    cp = configparser.RawConfigParser(interpolation=None, inline_comment_prefixes=None,
                                      comment_prefixes=("#",), strict=False)
    cp.optionxform = str.lower
    cp.read_string(read_text(path))
    pol = {"items": {}, "cats": {}}
    pol["library"] = cp.get("statement", "library").strip()
    pol["start"] = pdate(cp.get("statement", "period_start"))
    pol["end"] = pdate(cp.get("statement", "period_end"))
    base = parse_offset(cp.get("clock", "offset")) if cp.has_section("clock") and cp.has_option("clock", "offset") else 0
    changes = []
    if cp.has_section("clock") and cp.has_option("clock", "changes"):
        for part in cp.get("clock", "changes").split(";"):
            part = part.strip()
            if not part:
                continue
            inst, off = part.split()
            changes.append((parse_instant(inst), parse_offset(off)))
    changes.sort()
    pol["base"] = base
    pol["changes"] = changes
    for sec in cp.sections():
        low = sec.lower()
        if low.startswith("item:"):
            g = lambda k: cp.get(sec, k).strip()
            pol["items"][low[5:].strip()] = {
                "name": sec[5:].strip(),
                "loan_days": int(g("loan_days")),
                "renewals": int(g("renewals")),
                "grace": int(g("grace_days")),
                "daily": cents(g("daily")),
                "loan_cap": cents(g("loan_cap")),
            }
        elif low.startswith("category:"):
            cap = cp.get(sec, "statement_cap").strip()
            ex = cp.get(sec, "exempt").strip() if cp.has_option(sec, "exempt") else ""
            pol["cats"][low[9:].strip()] = {
                "name": sec[9:].strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(cp.get(sec, "discount").strip() or 0),
                "exempt": {x.strip().lower() for x in ex.split(",") if x.strip()},
            }
    return pol


def local_from_instant(pol, utc):
    off = pol["base"]
    for inst, o in pol["changes"]:
        if utc >= inst:
            off = o
        else:
            break
    return utc + timedelta(minutes=off)


def load_events(indir, pol):
    exdir = os.path.join(indir, "exports")
    events = {}
    for name in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, name)
        if not os.path.isfile(path):
            continue
        low = name.lower()
        if low.endswith(".csv"):
            rows = read_csv(path)
            for r in rows:
                eid = r.get("event", "").strip()
                if not eid or eid in events:
                    continue
                t = r.get("time", "").strip()
                lt = datetime.strptime(t, "%Y-%m-%d %H:%M")
                events[eid] = (r, lt)
        elif low.endswith(".jsonl"):
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                r = json.loads(line)
                eid = str(r.get("event", "")).strip()
                if not eid or eid in events:
                    continue
                r = {k: ("" if v is None else str(v)) for k, v in r.items()}
                lt = local_from_instant(pol, parse_instant(r["at"]))
                events[eid] = (r, lt)
    return events


class Calendar:
    def __init__(self, indir, branches):
        self.open_days = {}
        for b in branches:
            days = {d.strip().lower()[:3] for d in b["open_days"].split()}
            self.open_days[b["branch"].strip().upper()] = {i for i, w in enumerate(WEEKDAYS) if w in days}
        self.rows = {}
        for r in read_csv(os.path.join(indir, "calendar.csv")):
            ds = r["date"].strip()
            if ".." in ds:
                a, b = ds.split("..")
            else:
                a = b = ds
            key = r["branch"].strip().upper()
            self.rows.setdefault(key, []).append((pdate(a), pdate(b), r["status"].strip().lower() == "open"))
        self.cache = {}

    def _cover(self, key, d):
        res = None
        for a, b, st in self.rows.get(key, ()):
            if a <= d <= b:
                res = st
        return res

    def is_open(self, branch, d):
        key = (branch, d)
        if key in self.cache:
            return self.cache[key]
        bu = branch.strip().upper()
        res = self._cover(bu, d)
        if res is None:
            res = self._cover("*", d)
        if res is None:
            res = d.weekday() in self.open_days.get(bu, set())
        self.cache[key] = res
        return res

    def next_open(self, branch, d):
        n = 0
        while not self.is_open(branch, d) and n < 100000:
            d += timedelta(days=1)
            n += 1
        return d


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    pol = load_policy(os.path.join(indir, "policy.ini"))
    pstart, pend = pol["start"], pol["end"]
    branches = read_csv(os.path.join(indir, "branches.csv"))
    cal = Calendar(indir, branches)
    branch_ids = {b["branch"].strip().upper(): b["branch"].strip() for b in branches}

    patrons = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        n = pnum(r["patron"])
        patrons.setdefault(n, []).append((pdate(r["since"]), r["patron"].strip(), r["category"].strip()))
    for n in patrons:
        patrons[n].sort(key=lambda x: x[0])

    def category_on(n, d):
        cur = None
        for since, _, cat in patrons[n]:
            if since <= d:
                cur = cat
        if cur is None:
            cur = patrons[n][0][2]
        return pol["cats"][cur.lower()]

    waivers = {}
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r.get("status", "").strip().lower() != "active":
            continue
        n = pnum(r["patron"])
        v = r["value"].strip()
        val = "full" if v.lower() == "full" else cents(v)
        waivers.setdefault(n, []).append((r["loan"].strip(), val))

    events = load_events(indir, pol)

    cancelled = set()
    for eid, (r, lt) in events.items():
        if r.get("type", "").strip().lower() == "void":
            t = r.get("target", "").strip()
            if t:
                cancelled.add(t)

    checkouts = {}
    others = {}
    for eid, (r, lt) in events.items():
        if eid in cancelled:
            continue
        ty = r.get("type", "").strip().lower()
        loan = r.get("loan", "").strip()
        if ty == "checkout":
            checkouts[loan] = (r, lt)
        elif ty in ("renew", "return"):
            others.setdefault(loan, []).append((lt, ty, r))

    loans_by_patron = {}
    for lid, (r, lt) in checkouts.items():
        cdate = lt.date()
        if cdate > pend:
            continue
        item = pol["items"][r["item_type"].strip().lower()]
        bran = r["branch"].strip()
        due = cal.next_open(bran, cdate + timedelta(days=item["loan_days"]))
        renewals = 0
        returned = None
        for elt, ty, er in sorted(others.get(lid, []), key=lambda x: x[0]):
            ed = elt.date()
            if ty == "renew":
                if ed <= due and renewals < item["renewals"] and ed <= pend:
                    renewals += 1
                    due = cal.next_open(bran, ed + timedelta(days=item["loan_days"]))
            else:
                returned = ed
                if er.get("via", "").strip().lower() == "dropbox":
                    returned = ed - timedelta(days=1)
                break
        if returned is not None and returned < pstart:
            continue
        if returned is not None and returned > pend:
            returned = None
        end_day = returned if returned is not None else pend
        overdue = 0
        d = due + timedelta(days=1)
        while d <= end_day:
            if cal.is_open(bran, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue == 0:
            continue
        n = pnum(r["patron"])
        charged = overdue if overdue > item["grace"] else 0
        base = charged * item["daily"]
        cat = category_on(n, cdate)
        if item["name"].lower() in cat["exempt"] or r["item_type"].strip().lower() in cat["exempt"]:
            base = 0
        base = min(base, item["loan_cap"])
        assessed = (base * (100 - cat["discount"]) * 2 + 100) // 200
        loans_by_patron.setdefault(n, []).append({
            "loan": lid, "item": r.get("item", "").strip(), "item_type": item["name"],
            "branch": branch_ids.get(bran.upper(), bran),
            "checkout": cdate.isoformat(), "due": due.isoformat(),
            "returned": returned.isoformat() if returned else None,
            "overdue_days": overdue, "charged_days": charged,
            "assessed": assessed, "waived": 0, "capped": 0, "billed": 0,
            "_due": due,
        })

    statements = []
    for n in sorted(loans_by_patron):
        loans = loans_by_patron[n]
        loans.sort(key=lambda l: (l["_due"], l["loan"]))
        ws = waivers.get(n, [])
        for l in loans:
            app = [v for (wl, v) in ws if wl == "*" or wl == l["loan"]]
            if any(v == "full" for v in app):
                w = l["assessed"]
            else:
                w = min(sum(app), l["assessed"])
            l["waived"] = w
            l["billed"] = l["assessed"] - w
        rows = patrons[n]
        pat_name = [p for s, p, c in rows if s <= pend]
        pat_name = pat_name[-1] if pat_name else rows[0][1]
        cat = category_on(n, pend)
        if cat["cap"] is not None:
            excess = sum(l["billed"] for l in loans) - cat["cap"]
            for l in sorted(loans, key=lambda l: (l["_due"], l["loan"]), reverse=True):
                if excess <= 0:
                    break
                g = min(excess, l["billed"])
                l["capped"] = g
                l["billed"] -= g
                excess -= g
        for l in loans:
            del l["_due"]
        st = {"patron": pat_name, "category": cat["name"], "loans": loans}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(l[k] for l in loans)
        statements.append(st)

    summary = []
    for b in branches:
        bid = b["branch"].strip()
        ls = [l for s in statements for l in s["loans"] if l["branch"] == bid]
        e = {"branch": bid, "loans": len(ls)}
        for k in ("charged_days", "assessed", "waived", "capped", "billed"):
            e[k] = sum(l[k] for l in ls)
        summary.append(e)

    out = {"library": pol["library"], "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": statements, "branches": summary}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
        f.write("\n")


if __name__ == "__main__":
    main()
